  // Bottom face (back)
  const botCenter=positions.length/3;
  positions.push(0,-halfT,0); normals.push(0,-1,0); uvs.push(0.5,0.5);
  // Outer rings
  const topRingStart=positions.length/3;
  for(let i=0;i<=radialSegments;i++){
    const a=(i/radialSegments)*Math.PI*2;
    const x=Math.cos(a)*radius, z=Math.sin(a)*radius;
    positions.push(x,halfT,z); normals.push(0,1,0); uvs.push(0.5+Math.cos(a)*0.5,0.5+Math.sin(a)*0.5);
  }
  const botRingStart=positions.length/3;
  for(let i=0;i<=radialSegments;i++){
    const a=(i/radialSegments)*Math.PI*2;
    const x=Math.cos(a)*radius, z=Math.sin(a)*radius;
    positions.push(x,-halfT,z); normals.push(0,-1,0); uvs.push(0.5+Math.cos(a)*0.5,0.5+Math.sin(a)*0.5);
  }
  // Edge - reeded
  const edgeTopStart=positions.length/3;
  for(let i=0;i<=reeds;i++){
    const a=(i/reeds)*Math.PI*2;
    const x=Math.cos(a)*radius, z=Math.sin(a)*radius;
    positions.push(x,halfT,z);
    const nx=Math.cos(a), nz=Math.sin(a);
    normals.push(nx,0,nz);
    uvs.push(i/reeds,1);
  }
  const edgeBotStart=positions.length/3;
  for(let i=0;i<=reeds;i++){
    const a=(i/reeds)*Math.PI*2;
    const x=Math.cos(a)*radius, z=Math.sin(a)*radius;
    positions.push(x,-halfT,z);
    const nx=Math.cos(a), nz=Math.sin(a);
    normals.push(nx,0,nz);
    uvs.push(i/reeds,0);
  }
  // Indices
  // Top face triangles
  for(let i=0;i<radialSegments;i++){
    indices.push(topCenter, topRingStart+i+1, topRingStart+i);
