    uniform vec3 lightDir; uniform vec3 lightColor; uniform vec3 ambientColor;
    void main(){
      float facing=dot(vNormal,vec3(0.0,1.0,0.0));
      vec3 albedo;
      float faceMask=smoothstep(-0.05,0.05,facing);
      vec2 uvFront=vUv;
      vec2 uvBack=vec2(1.0-vUv.x,vUv.y);
      vec3 frontCol=texture2D(frontMap,uvFront).rgb;
      vec3 backCol=texture2D(backMap,uvBack).rgb;
      vec3 edgeCol=texture2D(edgeMap,vec2(vUv.x,0.5)).rgb;
      // Determine which face
      if(facing>0.1){
        albedo=mix(edgeCol,frontCol,faceMask);
      }else if(facing<-0.1){
        albedo=mix(edgeCol,backCol,faceMask);
      }else{
        albedo=edgeCol;
      }
      // Metallic workflow
      vec3 F0=mix(vec3(0.04),albedo,metalness);
      vec3 F=F0+(1.0-F0)*pow(1.0-max(dot(vViewDir,vNormal),0.0),5.0);
      // Lighting
      float NdotL=max(dot(vNormal,lightDir),0.0);
      float NdotV=max(dot(vViewDir,vNormal),0.0);
      // Specular highlight (GGX approx)
      vec3 H=normalize(vViewDir+lightDir);
      float NdotH=max(dot(vNormal,H),0.0);
      float alpha=roughness*roughness;
      float alpha2=alpha*alpha;
      float denom=NdotH*NdotH*(alpha2-1.0)+1.0;
      float D=alpha2/(3.14159*denom*denom);
      float k=(roughness+1.0)*(roughness+1.0)/8.0;
      float G_V=NdotV/(NdotV*(1.0-k)+k);
      float G_L=NdotL/(NdotL*(1.0-k)+k);
      float G=G_V*G_L;
      vec3 spec=(D*F*G)/(4.0*NdotV*NdotL+0.001);
      // Fresnel edge glow
      float fresnel=pow(1.0-NdotV,3.0);
      vec3 edgeGlow=mix(vec3(0.0),metalColor*1.5,fresnel*0.5);
      // Final color
      vec3 diffuse=albedo*(1.0-metalness)*(1.0-F)*NdotL*lightColor;
      vec3 ambient=albedo*ambientColor*(1.0-metalness);
      vec3 color=diffuse+spec*lightColor+ambient+edgeGlow;
      // Gamma
      color=pow(color,vec3(1.0/2.2));
      gl_FragColor=vec4(color,1.0);
    }
  `;
  return new THREE.ShaderMaterial({
    uniforms:{
      frontMap:{value:frontMap}, backMap:{value:backMap}, edgeMap:{value:edgeMap},
      metalColor:{value:metalColor}, roughness:{value:roughness}, metalness:{value:metalness},
      lightDir:{value:new THREE.Vector3(0.3,0.8,0.5).normalize()},
      lightColor:{value:new THREE.Color(1,0.95,0.85)},
      ambientColor:{value:new THREE.Color(0.15,0.12,0.1)},
      cameraPosition:{value:new THREE.Vector3()}
    },
    vertexShader, fragmentShader
  });
}

