class HeroCoin {
  constructor(canvas) {
    this.canvas=canvas;
    this.renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true,preserveDrawingBuffer:true});
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio,2));
    this.scene=new THREE.Scene();
    this.camera=new THREE.PerspectiveCamera(35,1,0.1,100);
    this.camera.position.set(0,0,3.5);
    this.camera.lookAt(0,0,0);
    // Textures
    this.frontTex=createEmblemTexture(512);
    this.backTex=createDenomTexture(512,'10,000 TOKENS');
    this.edgeTex=createEdgeTexture(512,80);
    // Geometry & Material
    this.geom=createCoinGeometry(1,0.12,64,80);
    this.material=createCoinMaterial(this.frontTex,this.backTex,this.edgeTex,new THREE.Color(0.95,0.85,0.65),0.12,0.98);
    this.coin=new THREE.Mesh(this.geom,this.material);
    this.scene.add(this.coin);
    // Lights (for fallback standard material if needed)
    this.scene.add(new THREE.AmbientLight(0x202020,1));
    const dl=new THREE.DirectionalLight(0xffffee,2);dl.position.set(2,4,3);this.scene.add(dl);
    const dl2=new THREE.DirectionalLight(0x8888aa,0.5);dl2.position.set(-2,-1,-2);this.scene.add(dl2);
    // Animation state
    this.time=0; this.paused=false; this.rafId=null;
    this.resize(); window.addEventListener('resize',()=>this.resize());
  }
  resize(){
    const rect=this.canvas.getBoundingClientRect();
    const w=rect.width,h=rect.height;
    this.renderer.setSize(w,h,false);
    this.camera.aspect=w/h; this.camera.updateProjectionMatrix();
  }
  setTime(t){
    this.time=t;
    this.renderFrame(t);
  }
  renderFrame(t){
    // t in [0,1] -> full loop
    // Rotate Y (vertical axis) 360 deg, flip X (horizontal) 180 deg over loop
    const yRot=t*Math.PI*2;
    const xRot=Math.sin(t*Math.PI*2)*Math.PI*0.5; // flips back and forth
    // Compose quaternion
    const qY=new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0,1,0),yRot);
    const qX=new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(1,0,0),xRot);
    this.coin.quaternion.copy(qY).multiply(qX);
    // Update camera position uniform
    this.material.uniforms.cameraPosition.value.setFromMatrixPosition(this.camera.matrixWorld);
    this.renderer.render(this.scene,this.camera);
  }
  animate(){
    if(this.paused)return;
    const now=performance.now()*0.001;
    const t=(now*0.15)%1; // 6.66s per loop
    this.renderFrame(t);
    this.rafId=requestAnimationFrame(()=>this.animate());
  }
  pause(){this.paused=true;if(this.rafId)cancelAnimationFrame(this.rafId);this.rafId=null;}
  resume(){if(this.paused){this.paused=false;this.animate();}}
  dispose(){this.pause();this.renderer.dispose();this.geom.dispose();this.material.dispose();this.frontTex.dispose();this.backTex.dispose();this.edgeTex.dispose();}
}

