class EditionCoin {
  constructor(canvas, edition) {
    this.canvas=canvas;
    this.edition=edition;
    this.renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true});
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio,2));
    this.scene=new THREE.Scene();
    this.camera=new THREE.PerspectiveCamera(35,1,0.1,100);
    this.camera.position.set(0,0,3.5);
    this.camera.lookAt(0,0,0);
    // Colors per edition
    const configs={
      bronze:{color:new THREE.Color(0.8,0.5,0.2), rough:0.3, metal:0.7, label:'BRONZE'},
      silver:{color:new THREE.Color(0.85,0.85,0.9), rough:0.15, metal:0.95, label:'SILVER'},
      gold:{color:new THREE.Color(1,0.84,0.15), rough:0.1, metal:1.0, label:'GOLD'},
      black:{color:new THREE.Color(0.12,0.12,0.14), rough:0.05, metal:0.98, label:'OBSIDIAN'}
    };
    const cfg=configs[edition]||configs.bronze;
    // Textures (shared geometry, different front/back textures per edition)
    this.frontTex=createEmblemTexture(256);
    this.backTex=createDenomTexture(256, edition==='gold'?'5,000 TOKENS': edition==='silver'?'7,500 TOKENS': edition==='bronze'?'10,000 TOKENS':'??? TOKENS');
    this.edgeTex=createEdgeTexture(256,60);
    this.geom=createCoinGeometry(1,0.12,48,60);
    this.material=createCoinMaterial(this.frontTex,this.backTex,this.edgeTex,cfg.color,cfg.rough,cfg.metal);
    this.coin=new THREE.Mesh(this.geom,this.material);
    // Set a nice static pose showing both faces slightly
    this.coin.rotation.y=-0.4;
    this.coin.rotation.x=-0.25;
    this.scene.add(this.coin);
    this.scene.add(new THREE.AmbientLight(0x202020,1));
    const dl=new THREE.DirectionalLight(0xffffee,1.5);dl.position.set(1.5,3,2);this.scene.add(dl);
    this.resize();
    this.render();
  }
  resize(){
    const rect=this.canvas.getBoundingClientRect();
    const w=rect.width,h=rect.height;
    if(w===0||h===0)return;
    this.renderer.setSize(w,h,false);
    this.camera.aspect=w/h; this.camera.updateProjectionMatrix();
    this.render();
  }
  render(){
    this.material.uniforms.cameraPosition.value.setFromMatrixPosition(this.camera.matrixWorld);
    this.renderer.render(this.scene,this.camera);
  }
  dispose(){this.renderer.dispose();this.geom.dispose();this.material.dispose();this.frontTex.dispose();this.backTex.dispose();this.edgeTex.dispose();}
}

